out = parse_params({"C": "1.0", "seed": "7", "features": "v3"}, {"C": float, "seed": int, "features": str})
assert out == {"C": 1.0, "seed": 7, "features": "v3"}
assert isinstance(out["seed"], int) and isinstance(out["C"], float)

try:
    parse_params({"C": "1.0"}, {"C": float, "seed": int, "alpha": float})
except KeyError as err:
    assert "alpha" in str(err) and "seed" in str(err)
else:
    raise AssertionError("no KeyError")

assert parse_params({"C": "2", "note": "x"}, {"C": float}) == {"C": 2.0}
try:
    parse_params({"seed": "seven"}, {"seed": int})
except ValueError:
    pass
else:
    raise AssertionError("bad value accepted")
